fn check_sample<T: Wire + Default + PartialEq + std::fmt::Debug>() -> Result<()> {
    let value = T::default();
    let mut writer = crate::io::Writer::new();
    value.encode(&mut writer)?;
    if value.compute_size()? != writer.len() {
        return Err(ProtocolError::RoundTripMismatch {
            type_name: std::any::type_name::<T>(),
        });
    }
    let mut reader = crate::io::Reader::new(writer.as_slice());
    let decoded = T::decode(&mut reader)?;
    if !reader.is_empty() {
        return Err(ProtocolError::RoundTripMismatch {
            type_name: std::any::type_name::<T>(),
        });
    }
    let mut again = crate::io::Writer::new();
    decoded.encode(&mut again)?;
    if again.as_slice() != writer.as_slice() {
        return Err(ProtocolError::RoundTripMismatch {
            type_name: std::any::type_name::<T>(),
        });
    }
    Ok(())
}

/// Protocol constants from `ProtocolSettings.java`.
pub mod settings {
    /// Protocol CRC expected in `Connect`.
    pub const CRC: i32 = -386561135;
    /// Protocol version.
    pub const VERSION: u32 = 3;
    /// Protocol build number.
    pub const BUILD_NUMBER: u32 = 258;
    /// Declared packet count.
    pub const PACKET_COUNT: usize = 389;
    /// Declared struct count.
    pub const STRUCT_COUNT: usize = 445;
    /// Declared enum count.
    pub const ENUM_COUNT: usize = 177;
    /// Maximum packet payload size.
    pub const MAX_PACKET_SIZE: u32 = 1677721600;
}
